from fractions import Fraction as Q
from math import factorial, comb
def fall(n,k):return 0 if k>n else factorial(n)//factorial(n-k)
def moment(p,a,n):return Q(0) if n%p else Q(factorial(n),factorial(n//p))*a**(n//p)
def appell(p,b,n):
    A={0:Q(1)}
    for _ in range(n):
        B={r+1:c for r,c in A.items()}
        for r,c in A.items():
            if r>=p-1:B[r-p+1]=B.get(r-p+1,Q(0))-p*b*fall(r,p-1)*c
        A={r:c for r,c in B.items() if c}
    return A
def ev(A,x):return sum(c*x**r for r,c in A.items())
def deriv(A,q):return {r-q:c*fall(r,q) for r,c in A.items() if r>=q}
steps=0;telescopes=0;parameters=0
for m in range(1,5):
    p=2*m
    for T in [Q(1),Q(1,2),Q(5,7)]:
        a=(-1)**(m+1)*T
        for degree in range(13):
            assert ev(appell(p,-a,degree),Q(0))==moment(p,a,degree)
            for N in [1,2,4,8]:
                h=Q(1,N);x=Q(0);total=Q(0)
                for j in range(N):
                    z=Q((-1)**j*(j+1),N+1);s=j*h;b=a*(s-1);right=appell(p,b+a*h,degree)
                    actual=ev(right,x+z)-ev(appell(p,b,degree),x)
                    expected=sum(ev(deriv(right,q),x)/factorial(q)*(z**q-moment(p,a*h,q))
                                 for q in range(1,degree+1))
                    assert actual==expected
                    for q in range(degree+2):
                        assert ev(deriv(right,q),x)==fall(degree,q)*ev(appell(p,b+a*h,max(degree-q,0)),x)
                    total+=expected;x+=z;steps+=1
                assert total==x**degree-moment(p,a,degree)
                telescopes+=1
            for b in [Q(0),Q(1),Q(-2),Q(3,7)]:
                explicit={degree-p*k:Q(factorial(degree),factorial(k)*factorial(degree-p*k))*(-b)**k
                          for k in range(degree//p+1)}
                explicit={r:c for r,c in explicit.items() if c}
                assert appell(p,b,degree)==explicit;parameters+=1
assert appell(4,Q(2),8)=={8:Q(1),4:Q(-3360),0:Q(80640)}
